// ─── Input Validator & Normalizer ───
const body = $input.first().json.body || $input.first().json;

const action = (body.action || '').toLowerCase().trim();
const question = (body.question || body.query || '').trim();
const paper_url = (body.paper_url || '').trim();
const streamlit_url = (body.streamlit_url || 'http://localhost:8501').trim();

// Validate required fields
if (!action) {
  return [{
    json: {
      error: true,
      message: "❌ 'action' field required. Options: chat | summarize | compare | gap | search"
    }
  }];
}

const valid_actions = ['chat', 'summarize', 'compare', 'gap', 'search', 'status'];
if (!valid_actions.includes(action)) {
  return [{
    json: {
      error: true,
      message: `❌ Invalid action '${action}'. Valid: ${valid_actions.join(' | ')}`
    }
  }];
}

return [{
  json: {
    error: false,
    action: action,
    question: question,
    paper_url: paper_url,
    streamlit_url: streamlit_url,
    timestamp: new Date().toISOString(),
    raw_body: body
  }
}];

// Parse AI Agent response and build final request
const aiResponse = $input.first().json;
const originalInput = $('🔍 Validate & Parse Input').first().json;

let parsed;
try {
  // AI returns JSON string in message content
  const content = aiResponse.content || aiResponse.text || aiResponse.message || JSON.stringify(aiResponse);
  const cleanContent = content.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleanContent);
} catch(e) {
  parsed = {
    endpoint: '/api/chat',
    method: 'POST',
    payload: { question: originalInput.question, action: originalInput.action },
    human_response: 'Processing your request...',
    confidence: 'low',
    action_taken: originalInput.action
  };
}

const streamlit_url = originalInput.streamlit_url || 'http://localhost:8501';

return [{
  json: {
    full_url: streamlit_url + parsed.endpoint,
    method: parsed.method || 'POST',
    payload: {
      ...parsed.payload,
      question: originalInput.question,
      action: originalInput.action,
      timestamp: originalInput.timestamp
    },
    human_response: parsed.human_response,
    confidence: parsed.confidence,
    action_taken: parsed.action_taken,
    streamlit_url: streamlit_url
  }
}];

// Format final response
const httpResult = $input.first().json;
const buildData = $('🔧 Build API Request').first().json;

let app_response = '';
let success = true;

// Check if HTTP call succeeded
if (httpResult.error || httpResult.statusCode >= 400) {
  // Streamlit ka direct API nahi hai — fallback response
  success = false;
  app_response = `⚠️ Streamlit app se direct response nahi mila. 

Action: ${buildData.action_taken}
Endpoint tried: ${buildData.full_url}

💡 Yeh normal hai agar Streamlit app mein REST API endpoints configure nahi kiye.
Neeche bataya gaya hai kya karna hai.`;
} else {
  app_response = httpResult.result || httpResult.answer || httpResult.response || JSON.stringify(httpResult);
}

return [{
  json: {
    success: success,
    action: buildData.action_taken,
    ai_understanding: buildData.human_response,
    confidence: buildData.confidence,
    app_response: app_response,
    streamlit_url: buildData.streamlit_url,
    timestamp: new Date().toISOString(),
    note: success ? '' : 'REST API endpoints app.py mein add karne honge'
  }
}];
